package com.jobpilot.integration;import com.fasterxml.jackson.annotation.JsonIgnoreProperties;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.*;
@Component public class AdzunaClient{private final String id,key;private final RestClient http=RestClient.create("https://api.adzuna.com/v1/api/jobs");public AdzunaClient(@Value("${app.adzuna-app-id}")String id,@Value("${app.adzuna-app-key}")String key){this.id=id;this.key=key;}public List<Result>search(SearchPreference p){if(id.isBlank()||key.isBlank())return List.of();var response=http.get().uri(b->b.path("/{country}/search/1").queryParam("app_id",id).queryParam("app_key",key).queryParam("results_per_page",20).queryParam("what",p.getKeywords()).queryParam("where",p.getLocation()).build(p.getCountry())).retrieve().body(Response.class);return response==null||response.results()==null?List.of():response.results();}@JsonIgnoreProperties(ignoreUnknown=true)public record Response(List<Result>results){}@JsonIgnoreProperties(ignoreUnknown=true)public record Result(String id,String title,Company company,Location location,String description,String redirect_url,BigDecimal salary_min,BigDecimal salary_max,OffsetDateTime created){}@JsonIgnoreProperties(ignoreUnknown=true)public record Company(String display_name){}@JsonIgnoreProperties(ignoreUnknown=true)public record Location(String display_name){}}
